def page(title,*sections):return {'title':title,'sections':list(sections)}
def sec(title,text):return {'title':title,'text':text}
def table(title,heads,rows):return {'title':title,'heads':heads,'rows':rows}
def doc(name,title,pages):docs.append({'name':name,'title':title,'pages':pages})
