# Modelo BPMN de camino principal, con DI para importación en modeladores.
import xml.etree.ElementTree as ET
NS={'bpmn':'http://www.omg.org/spec/BPMN/20100524/MODEL','bpmndi':'http://www.omg.org/spec/BPMN/20100524/DI','dc':'http://www.omg.org/spec/DD/20100524/DC','di':'http://www.omg.org/spec/DD/20100524/DI'}
for prefix,uri in NS.items():ET.register_namespace(prefix,uri)
def elem(prefix,name):return '{'+NS[prefix]+'}'+name
root=ET.Element(elem('bpmn','definitions'),{'id':'TecnicoYaDefinitions','targetNamespace':'https://tecnicoya.example/bpmn'})
process=ET.SubElement(root,elem('bpmn','process'),{'id':'ProcesoPrincipal','name':'TécnicoYa camino principal para revisión','isExecutable':'false'})
nodes=[('startEvent','inicio','Necesidad de servicio'),('task','solicitud','Cliente registra solicitud'),('task','ranking','Sistema ordena candidatos'),('task','oferta','Sistema genera ofertas'),('task','acepta','Técnico acepta'),('task','confirma','Cliente confirma'),('task','ejecuta','Técnico ejecuta y finaliza'),('task','nota','Cliente califica'),('endEvent','fin','Servicio evaluado')]
for typ,id,name in nodes:ET.SubElement(process,elem('bpmn',typ),{'id':id,'name':name})
for i in range(len(nodes)-1):ET.SubElement(process,elem('bpmn','sequenceFlow'),{'id':f'f{i}','sourceRef':nodes[i][1],'targetRef':nodes[i+1][1]})
diagram=ET.SubElement(root,elem('bpmndi','BPMNDiagram'),{'id':'diagrama'});plane=ET.SubElement(diagram,elem('bpmndi','BPMNPlane'),{'id':'plano','bpmnElement':'ProcesoPrincipal'})
for i,(typ,id,name) in enumerate(nodes):
    shape=ET.SubElement(plane,elem('bpmndi','BPMNShape'),{'id':id+'_di','bpmnElement':id});size=36 if 'Event' in typ else 120
    ET.SubElement(shape,elem('dc','Bounds'),{'x':str(30+i*155),'y':'80','width':str(size),'height':str(36 if 'Event' in typ else 70)})
for i in range(len(nodes)-1):
    edge=ET.SubElement(plane,elem('bpmndi','BPMNEdge'),{'id':f'f{i}_di','bpmnElement':f'f{i}'})
    ET.SubElement(edge,elem('di','waypoint'),{'x':str(30+i*155+(36 if i==0 else 120)),'y':'110'});ET.SubElement(edge,elem('di','waypoint'),{'x':str(30+(i+1)*155),'y':'110'})
ET.ElementTree(root).write(EDIT/'proceso-principal.bpmn',encoding='utf-8',xml_declaration=True)
